ref_dict.th:f-vectors:
\begin{theorem}\label{th:f-vectors}
Take any $n\ge3$, and any $C>0$.
Then there is a triangulation of $\SS^n$ for which $\frac{f_j}{f_i}>C$
for any $0\le i<j\le n$ such that $i<\lfloor\frac {n-1}2\rfloor$.
\end{theorem}

ref_dict.thm:main-theorem-intro:
\begin{lettertheorem}\label{thm:main-theorem-intro}
  Let $p>3$ be prime. Let $K$ be a $p$-adic field that is totally ramified over $\Q_p$. Let $E_1$ and $E_2$ be elliptic curves defined over $K$ with full $K$-rational 2-torsion and supersingular reduction. Then for any $n>0$, there exists a WR relation $\{P_1,P_2\}_{K/K}=0$ in $K(K;E_1,E_2)$ of signature $(n,n)$.
\end{lettertheorem}

