theorem.content:
\label{lem:minimaxless}
Let $X\subseteq \mathbb{R}^d$, $Y\subseteq \mathbb{R}^k$, and $f:X\times Y \to \mathbb{R}$.
Then 
\begin{equation}\label{eq:minimaxless}
\sup_{\mathbf{x}\in X} \inf_{\mathbf{y}\in Y} f(\mathbf{x},\mathbf{y}) \leq \inf_{\mathbf{y}\in Y} \sup_{\mathbf{x}\in X} f(\mathbf{x},\mathbf{y}).
\end{equation}

ref_dict.lem:minimaxless:
\begin{lemma}\label{lem:minimaxless}
Let $X\subset \R^d$, $Y\subset \R^k$, and $f:X\times Y \to \R$.
Then 
\begin{equation}\label{eq:minimaxless}
\sup_{\x\in X} \inf_{\y\in Y} f(\x,\y) \leq \inf_{\y\in Y} \sup_{\x\in X} f(\x,\y).
\end{equation}
\end{lemma}

ref_dict.eq:minimaxless:
\begin{equation}\label{eq:minimaxless}
\sup_{\x\in X} \inf_{\y\in Y} f(\x,\y) \leq \inf_{\y\in Y} \sup_{\x\in X} f(\x,\y).
\end{equation}

post_theorem_intro_text:
\begin{proof}
For any $\x_0\in X$ we have
\[\inf_{\mathbf{y}\in Y} f(\x_0,\mathbf{y}) \leq \inf_{\mathbf{y}\in Y} \sup_{\mathbf{x}\in X} f(\mathbf{x},\mathbf{y}).\]
Taking the supremum over $\x_0\in X$ gives \eqref{eq:minimaxless}.
\end{proof}
By Lemma \ref{lem:minimaxless}, to prove a minimax theorem, it is sufficient to show the opposite inequality, namely that
\begin{equation}\label{eq:opp_ineq}
\inf_{\mathbf{y}\in Y} \sup_{\mathbf{x}\in X} f(\mathbf{x},\mathbf{y}) \leq \sup_{\mathbf{x}\in X} \inf_{\mathbf{y}\in Y} f(\mathbf{x},\mathbf{y}).
\end{equation}
However, this direction is much more difficult to prove, and does not always hold. 
\begin{example}\label{Ex:difference}
Let $X = \{-1,1\}\subseteq \mathbb{R}$, $Y = [-1,1]\subseteq \mathbb{R}$, and $f(x,y) = xy$. Then 
\[\max_{x\in X}\min_{y\in Y}f(x,y) = \max_{x\in X} (-1) = -1,\]
while 
\[\min_{y\in Y}\max_{x\in X}f(x,y) = \min_{y\in Y} |y| = 0.\]
\end{example}
As we shall see below, convexity of the sets $X$ and $Y$ play a key role in minimax theorems. Note that $X=\{-1,1\}$ is not a convex set.

