    \label{Proposition:Phi:compact}
    The input-output operator $\Psi:L^2(0,T;L^2(\Omega))\to L^2(\Omega)$ is compact.
\end{proposition}

ref_dict.proposition:existence:strong:solutions:
\begin{proposition}
    \label{proposition:existence:strong:solutions}
    Let $\Omega\subset \mathbb{R}^N$ be a bounded domain with $C^2$ boundary and let $T>0$. Assume that the coefficients $\alpha$ and $\beta$ satisfy 
    \begin{align}
        \label{assumption:prop:existence:02:alpha:beta}
        \alpha,\beta\in W^{1,\infty}(\Omega;\mathbb{R}),\quad \alpha(x)\geq \alpha_0 >0\text{ almost everywhere in }\Omega.
    \end{align}
    Moreover, consider \eqref{prop:existence:statement:02}, $v_0\in H_0^1(\Omega)$ and $h\in L^2(0,T;L^2(\Omega))$. Then, there exists a strong solution $v$ of \eqref{problem:existence:uniqueness} satisfying
    \begin{align*}
        v\in H^1(0,T;L^2(\Omega)) \cap C^0([0,T];H_0^1(\Omega)) \cap L^2(0,T; H^2(\Omega) \cap H_0^1(\Omega)).
    \end{align*}

    Moreover, there exists a constant $C>0$ depending only on $\alpha_0$, $\|\alpha\|_{W^{1,\infty}}$, $\||\vec{\sigma}|\|_{L^\infty}$, $\|p\|_\infty$, $\Omega$ and $T$ such that 
    \begin{align*}
        \begin{split} 
        &\|v\|_{L^2(0,T;H^2(\Omega))} + \|v\|_{C^0([0,T];H_0^1(\Omega))} + \|\pt v\|_{L^2(0,T;L^2(\Omega))} \\
        \leq &C\left(\|h\|_{L^2(0,T;L^2(\Omega))} + \|v_0\|_{H_0^1(\Omega)} \right).
        \end{split}
    \end{align*}
\end{proposition}

post_theorem_intro_text:
\begin{proof}
    Let $(f_k)_{k\in \mathbb{N}}$ be a bounded sequence in $L^2(\Omega\times (0,T))$. Then, by Proposition \ref{proposition:existence:strong:solutions}, the sequence of associated weak solutions $(y(\cdot,,\cdot,f_k))_{k\in \mathbb{N}}$ is bounded in $C^0([0,T];H_0^1(\Omega))$. In particular, the sequence $(Y_k)_{k\in \mathbb{N}}$ given by $Y_k:=y(\cdot,T,f_k)$ is bounded in $H_0^1(\Omega)\cap H^2(\Omega)$. Thus, using the Sobolev-Gagliardo-Nirenberg compact embedding $H_0^1(\Omega) \hookrightarrow L^2(\Omega)$, there exists a subsequence of $ (Y_k)_{k\in \mathbb{N}}$ which converges strongly in $L^2(\Omega)$. This implies that the input-output operator $\Psi$ is compact and the proof of Proposition  \ref{Proposition:Phi:compact} is finished. 
\end{proof}

In view of the Proposition \ref{Proposition:Phi:compact}, it is evident that the inverse problem {\bf (ISP)} is ill-posed in the sense of Hadamard. For this reason, one needs to introduce the functional $\mathcal{J}:\mathcal{U}\to \mathbb{R}$ by
\begin{align}
    \label{def:functional:J}
    \mathcal{J}(f):=\frac{1}{2}\int_\Omega |\Psi(f)-u_T|^2\,dx,
\end{align}
and reformulate {\bf (ISP)} in terms of the quasi-solution method, i.e., we minimize the following extremal problem
\begin{align*}
    \mathcal{J}(f^\star)=\inf_{f\in \mathcal{U}} \mathcal{J}(f).
\end{align*}

Since the operator $\Psi$ is compact, small perturbations in the data may cause large variations in the reconstructed source. Therefore, regularization becomes essential to obtain stable approximations. In this context, it is customary to consider a regularized Tikhonov version of the functional $J$ in \eqref{def:functional:J}. For $\epsilon>0$, we introduce the regularized functional
\begin{align}\label{regfunct}
    \mathcal{J}_\epsilon (f):=\frac{1}{2}\int_\Omega |\Psi(f)-u_T|^2\,dx + \frac{\epsilon}{2}\int_0^T\int_\Omega |f|^2\,dx\,dt ,\quad f\in \mathcal{U}. 
\end{align}

\subsection{Outline}
The rest of the paper is as follows. In Section \ref{section:Frechet:formula}, we focus on the properties of $J$, i.e., a detailed characterization of its Fr\'echet derivative via a suitable adjoint system. In Section \ref{section:Existence:ISP}, we give sufficient conditions for the existence and uniqueness of quasi-solutions to {\bf (ISP)}. In Section \ref{section:Numerical:experiments}, we validate our theoretical results by some numerical experiments to reconstruct source terms for 1-D and 2-D case. Finally, in Section \ref{section:Summary:perspectives} we give additional comments concerning the theoretical and numerical results obtained in this article.

